/** Actual saved-document professional findings. No candidate status is accepted or promoted. */
public final class DocumentReviewResultService {
    public static final String COVERAGE_REF="urn:medical:document-review-coverage:1.0.0";
    private final JdbcTemplate db;private final ResourceReadAuthority resources;private final DocumentReviewInvocationService invocations;private final DocumentReadService documents;private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema();
    private final TaskSourceVerifierNormalizer normalizer=new TaskSourceVerifierNormalizer(json);private final SchemaCatalogue schemas;
    public DocumentReviewResultService(DataSource data,ResourceReadAuthority resources,DocumentReviewInvocationService invocations,DocumentReadService documents)throws Exception{this.resources=resources;this.invocations=invocations;this.documents=documents;db=new JdbcTemplate(data);db.setQueryTimeout(5);schemas=SchemaCatalogue.fromClasspath();}
    Produced produce(EnterpriseAccess.Admission a,DocumentReviewInvocationService.Terminal terminal)throws Exception {
        terminal.requireCurrent(a);var target=terminal.document();var h=target.header();var rules=terminal.rules();var readPins=terminal.independentReads();
        same(terminal.sessionId(),text(readPins,"session_id"));if(terminal.writerSessionIds().contains(terminal.sessionId()))deny();
        var sources=new LinkedHashMap<DatasetProtocol.EvidenceRef,TaskSourceVerifierNormalizer.Read>();var sourceJson=new TaskSourceReadReceiptSchema(new PermissionSchema());
        for(var r:readPins.required("sources")){var ref=sourceJson.evidence(r.required("evidence_ref"));if(!target.evidenceRefs().contains(ref)||sources.putIfAbsent(ref,new TaskSourceVerifierNormalizer.Read(terminal.sessionId(),text(r,"receipt_id"),ref,bool(r,"access"),bool(r,"located"),bool(r,"complete")))!=null)bad();}
        var claims=target.claims();var claimReads=new LinkedHashMap<String,List<TaskSourceVerifierNormalizer.Read>>();
        for(var c:claims.values()){var reads=new ArrayList<TaskSourceVerifierNormalizer.Read>();var seen=new HashSet<DatasetProtocol.EvidenceRef>();for(var e:c.evidenceLinks())if(seen.add(e.evidenceRef())&&sources.containsKey(e.evidenceRef()))reads.add(sources.get(e.evidenceRef()));claimReads.put(c.claimId(),reads);}
        var body=target.body();var sections=new ArrayList<String>();JsonNode first=null;for(var n:body.required("nodes"))if("SECTION".equals(n.required("content").path("kind").asText())){sections.add(text(n,"node_id"));if(first==null)first=n;}if(first==null)bad();
        var anchor=new ArtifactProtocol.StructuredAnchor("STRUCTURED",sections.get(0),null,null,json.hash(first));var required=new LinkedHashMap<String,TaskSourceVerifierNormalizer.Rule>();for(String rule:rules.ruleIds())required.put(rule,new TaskSourceVerifierNormalizer.Rule(rule,sections,anchor,rules.deterministicResult(rule)));
        var readRules=new LinkedHashSet<String>();for(var r:readPins.required("rule_ids"))if(!r.isTextual()||!required.containsKey(r.asText())||!readRules.add(r.asText()))bad();
        var fixed=new TaskSourceVerifierNormalizer.Fixed(h.documentRevision(),h.bodySha256(),terminal.ruleRevision(),terminal.sessionId(),terminal.writerSessionIds(),body,claims,required,claimReads,readRules,target.evidenceRefs());
        var contract=terminal.runtime().evidenceContract();target.requireEvidenceContract(contract);
        var normalized=normalizer.normalizeDocument(fixed,terminal.hostActionId(),terminal.projection(),contract.artifactRef("ReviewFindings"),contract.artifactSha());
        var output=new ArtifactProtocol.ReviewOutput("REVIEW_FINDINGS",normalized.findings());
        var artifact=new ArtifactProtocol.ProfessionalArtifact(contract.version(),ArtifactProtocol.ExecutionKind.SYSTEM_JOB,h.tenantId(),h.projectId(),terminal.runId(),terminal.stepId(),terminal.inputSha256(),null,null,sections,accessSet(terminal.hostActionId()),json.hash(output),output);
        ArtifactEvidenceBindings.bind(schemas,ArtifactBindings.ARTIFACT,json.tree(artifact),contract.artifactRef(null),contract.artifactSha()).read();byte[] findings=json.bytes(artifact);
        var coverage=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("node_kind","N07").put("input_sha256",terminal.inputSha256()).put("session_id",terminal.sessionId()).put("target_revision",h.documentRevision()).put("target_sha256",h.bodySha256()).put("rule_revision",terminal.ruleRevision()).put("findings_sha256",WireValues.sha256(findings)).put("coverage_complete",normalized.findings().coverageComplete());
        coverage.set("required_claim_ids",json.tree(normalized.findings().requiredClaimIds()));coverage.set("required_rule_ids",json.tree(normalized.findings().requiredRuleIds()));coverage.set("checks",normalized.pins().required("coverage"));coverage.set("independent_reads",readPins);
        validateCoverage(coverage);terminal.requireCurrent(a);return new Produced(terminal,normalized,findings,json.bytes(coverage),contract);
    }
    /** All physical artifacts must already be re-read and registered by the private object ledger. */
    VerifiedCompletion submitSaved(EnterpriseAccess.Admission a,Produced p,DocumentReviewObjectLedger.Registered findings,DocumentReviewObjectLedger.Registered coverage)throws Exception {
        p.requireCurrent(a);findings.requireCurrent(a,p,"REVIEW_FINDINGS");coverage.requireCurrent(a,p,"REVIEW_COVERAGE");var t=p.terminal;var runtime=t.runtime();var h=t.document().header();
        var previous=db.queryForList("SELECT * FROM document_review_result WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2 FOR UPDATE",h.tenantId(),t.runId(),t.stepId(),t.hostActionId());if(!previous.isEmpty()){var done=completion(a,p,findings,coverage,one(previous));runtime.acceptedResult(done);return done;}
        var f=p.normalized.findings();boolean blocked=!f.coverageComplete()||!f.issueProposals().isEmpty()||f.claimChecks().stream().anyMatch(c->c.supportCheck()==ArtifactProtocol.SupportCheck.INSUFFICIENT||c.supportCheck()==ArtifactProtocol.SupportCheck.CONTRADICTED)||f.ruleChecks().stream().anyMatch(r->r.result()==ArtifactProtocol.RuleResult.FAIL||r.result()==ArtifactProtocol.RuleResult.BLOCKED);
        String check=derived(t.hostActionId(),"CHECK_RUN"),receiptId=derived(t.hostActionId(),"RESULT"),audit=id(),event=id();var at=now();var marks=one(db.queryForList("SELECT issue_watermark,evidence_watermark FROM document_revision_state WHERE tenant_id=? AND project_id=? AND document_revision=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision()));
        var receipt=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("node_kind","N07").put("execution_kind","SYSTEM_JOB").put("job_type","CHECK_DOCUMENT").put("target_kind","DOCUMENT").put("run_id",t.runId()).put("step_id",t.stepId()).put("action_id",t.hostActionId()).put("input_sha256",t.inputSha256()).put("receipt_id",receiptId).put("document_id",h.documentId()).put("document_revision",h.documentRevision()).put("body_sha256",h.bodySha256()).put("baseline_sha256",t.document().baselineSha256()).put("rule_manifest_id",t.ruleRevision()).put("rules_sha256",t.rules().sha256()).put("status",blocked?"WAITING_INPUT":"SUCCEEDED").put("professional_approval",false).put("coverage_complete",f.coverageComplete()).put("findings_artifact_id",findings.artifactId()).put("coverage_artifact_id",coverage.artifactId()).put("findings_sha256",findings.reference().sha256()).put("coverage_sha256",coverage.reference().sha256()).put("audit_id",audit).put("event_id",event);
        receipt.set("check_ids",json.tree(List.of(check)));receipt.set("input_watermarks",json.tree(marks));
        var row=meta(a,h,at);row.putAll(Map.of("check_id",check,"target_kind","DOCUMENT","target_id",h.documentId(),"target_revision",h.documentRevision(),"input_sha256",t.inputSha256(),"scope_manifest_id",runtime.job().scopeId(),"rule_manifest_id",t.ruleRevision(),"rule_manifest",json.canonical(t.rules().manifest()),"input_watermarks",json.canonical(t.document().baseline())));row.putAll(Map.of("evidence_watermark",marks.get("evidence_watermark"),"issue_watermark",marks.get("issue_watermark"),"coverage_artifact_id",coverage.artifactId(),"findings_artifact_id",findings.artifactId(),"result_ref",json.canonical(receipt),"status",blocked?"WAITING_INPUT":"SUCCEEDED","revision",1,"updated_at",at));
        // The SYSTEM_JOB run/step/action binding is preserved, never a former candidate TASK.
        row.put("run_id",t.runId());row.put("step_id",t.stepId());row.put("action_id",t.hostActionId());insert("check_run",row);
        int issueTransitions=0;var issueEffects=receipt.putArray("issue_effects");
        for(var issue:f.issueProposals()){
            String hash=json.hash(issue);var semantic=(com.fasterxml.jackson.databind.node.ObjectNode)json.tree(issue);semantic.remove(List.of("issue_key","message"));String semanticHash=json.hash(semantic);var previousIssues=db.queryForList("SELECT issue_id,status,revision FROM issue WHERE tenant_id=? AND project_id=? AND document_revision=? AND semantic_sha256=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision(),semanticHash);
            String issueId,effect;
            if(previousIssues.isEmpty()){
                issueId=derived(t.hostActionId(),issue.issueKey());var issueRow=meta(a,h,at);issueRow.putAll(Map.of("issue_id",issueId,"check_id",check,"document_revision",h.documentRevision(),"position",json.canonical(issue.anchor()),"severity","BLOCKING","code",issue.code(),"finding_sha256",hash,"status","OPEN","revision",1,"updated_at",at));issueRow.put("semantic_sha256",semanticHash);insert("issue",issueRow);issueTransitions++;effect="CREATED";
            }else{
                var old=one(previousIssues);issueId=str(old,"issue_id");effect="UNCHANGED";
                if("RESOLVED".equals(str(old,"status"))){if(db.update("UPDATE issue SET status='REOPENED',resolution_ref=NULL,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND issue_id=? AND revision=? AND status='RESOLVED'",at,h.tenantId(),h.projectId(),issueId,old.get("revision"))!=1)stale();issueTransitions++;effect="REOPENED";}
            }
            var occurrence=meta(a,h,at);occurrence.putAll(Map.of("check_id",check,"issue_id",issueId,"document_revision",h.documentRevision(),"finding_sha256",hash,"semantic_sha256",semanticHash,"effect",effect));insert("professional_issue_occurrence",occurrence);
            issueEffects.addObject().put("issue_id",issueId).put("finding_sha256",hash).put("effect",effect);
        }
        if(issueTransitions>0&&db.update("UPDATE document_revision_state SET issue_watermark=issue_watermark+?,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND document_revision=?",issueTransitions,at,h.tenantId(),h.projectId(),h.documentRevision())!=1)stale();
        // Preserve the input receipt and hash. Only the actual committed issue insert delta defines output currentness.
        var outputMarks=one(db.queryForList("SELECT issue_watermark,evidence_watermark FROM document_revision_state WHERE tenant_id=? AND project_id=? AND document_revision=? LIMIT 2 FOR UPDATE",h.tenantId(),h.projectId(),h.documentRevision()));
        same(str(marks,"evidence_watermark"),str(outputMarks,"evidence_watermark"));
        same(new java.math.BigInteger(str(marks,"issue_watermark")).add(java.math.BigInteger.valueOf(issueTransitions)).toString(),str(outputMarks,"issue_watermark"));
        receipt.set("output_watermarks",json.tree(outputMarks));validateResult(receipt);
        if(db.update("UPDATE check_run SET issue_watermark=?,evidence_watermark=?,result_ref=? WHERE tenant_id=? AND project_id=? AND check_id=? AND revision=1",outputMarks.get("issue_watermark"),outputMarks.get("evidence_watermark"),json.canonical(receipt),h.tenantId(),h.projectId(),check)!=1)bad();
        if(!blocked){
            db.update("UPDATE section_revision s JOIN document_section d ON d.tenant_id=s.tenant_id AND d.project_id=s.project_id AND d.section_revision=s.section_revision SET s.status='REVIEW_PENDING' WHERE d.tenant_id=? AND d.project_id=? AND d.document_revision=? AND s.status='DRAFT_CHECK_PENDING'",h.tenantId(),h.projectId(),h.documentRevision());
            if(db.update("UPDATE document_head SET status='REVIEW_PENDING',revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND document_id=? AND current_document_revision=? AND status<>'SIGNED'",at,h.tenantId(),h.projectId(),h.documentId(),h.documentRevision())!=1)stale();
        }
        var stored=meta(a,h,at);stored.putAll(Map.of("run_id",t.runId(),"step_id",t.stepId(),"action_id",t.hostActionId(),"check_id",check,"receipt_id",receiptId,"receipt_json",json.canonical(receipt),"receipt_sha256",json.hash(receipt),"findings_artifact_id",findings.artifactId(),"coverage_artifact_id",coverage.artifactId()));insert("document_review_result",stored);
        var log=meta(a,h,at);log.putAll(Map.of("audit_id",audit,"subject_id",a.actorId(),"action","document.professional_review.recorded","resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",t.hostActionId(),"trace_id",t.runId()));insert("audit_event",log);insert("outbox_event",Map.of("tenant_id",h.tenantId(),"event_id",event,"aggregate_id",check,"aggregate_revision",1,"event_type","document.professional_review.recorded","payload",json.canonical(receipt),"occurred_at",at));
        var done=new VerifiedCompletion(t.runId(),t.stepId(),t.inputSha256(),receipt,json.hash(receipt));runtime.acceptedResult(done);return done;
    }
    private VerifiedCompletion completion(EnterpriseAccess.Admission a,Produced p,DocumentReviewObjectLedger.Registered findings,DocumentReviewObjectLedger.Registered coverage,Map<String,Object> row)throws Exception {
        var receipt=json.read(str(row,"receipt_json"));same(json.hash(receipt),str(row,"receipt_sha256"));same(findings.artifactId(),text(receipt,"findings_artifact_id"));same(coverage.artifactId(),text(receipt,"coverage_artifact_id"));same(p.terminal.inputSha256(),text(receipt,"input_sha256"));var check=one(db.queryForList("SELECT result_ref,invalidation_reason FROM check_run WHERE tenant_id=? AND check_id=? AND target_kind='DOCUMENT' AND target_revision=? LIMIT 2 FOR UPDATE",p.terminal.document().header().tenantId(),str(row,"check_id"),p.terminal.document().header().documentRevision()));if(check.get("invalidation_reason")!=null)stale();same(receipt,json.read(str(check,"result_ref")));return new VerifiedCompletion(p.terminal.runId(),p.terminal.stepId(),p.terminal.inputSha256(),receipt,str(row,"receipt_sha256"));
    }
    /** Factual original-result recovery. Does not reopen the job or require its expired lease. */
    VerifiedCompletion readOriginal(EnterpriseAccess.Admission a,DocumentReviewExecutionService.Job job)throws Exception {
        same(a.context().tenant_id(),job.tenant());same(a.actorId(),job.actor());
        var metadata=documents.authorizeMetadata(a,a.context().context_revision(),job.document(),job.documentRevision());same(job.documentRevision(),metadata.header().currentDocumentRevision());var originalBaseline=json.read(job.baselineJson());same(a.context().auth_epoch(),text(originalBaseline,"auth_epoch"));same(a.context().governance_epoch(),text(originalBaseline,"governance_epoch"));
        resources.require(a,new PermissionProtocol.Scope(job.tenant(),job.project(),"DOCUMENT",job.document()),"document.read","DOCUMENT_BODY");
        resources.require(a,new PermissionProtocol.Scope(job.tenant(),job.project(),"DOCUMENT",job.document()),"document.check","DOCUMENT_BODY");
        var execution=one(db.queryForList("SELECT admission_json,input_sha256 FROM document_review_execution WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",job.tenant(),job.run()));same(job.admissionJson(),str(execution,"admission_json"));same(job.inputHash(),str(execution,"input_sha256"));
        var records=db.queryForList("SELECT * FROM document_review_result WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? LIMIT 2 FOR UPDATE",job.tenant(),job.run(),job.step(),job.action());
        if(records.isEmpty())return null;var row=one(records);var r=json.read(str(row,"receipt_json"));same(json.hash(r),str(row,"receipt_sha256"));same(job.inputHash(),text(r,"input_sha256"));same(job.documentRevision(),text(r,"document_revision"));
        var h=one(db.queryForList("SELECT h.current_document_revision,m.body_sha256 FROM document_head h JOIN document_revision_meta m ON m.tenant_id=h.tenant_id AND m.project_id=h.project_id AND m.document_id=h.document_id AND m.document_revision=h.current_document_revision WHERE h.tenant_id=? AND h.project_id=? AND h.document_id=? LIMIT 2 FOR UPDATE",job.tenant(),job.project(),job.document()));same(job.documentRevision(),str(h,"current_document_revision"));same(text(r,"body_sha256"),str(h,"body_sha256"));
        var check=one(db.queryForList("SELECT * FROM check_run WHERE tenant_id=? AND project_id=? AND check_id=? AND target_kind='DOCUMENT' AND target_revision=? LIMIT 2 FOR UPDATE",job.tenant(),job.project(),str(row,"check_id"),job.documentRevision()));if(check.get("invalidation_reason")!=null)stale();same(r,json.read(str(check,"result_ref")));same(job.ruleId(),str(check,"rule_manifest_id"));
        for(var rule:json.read(str(check,"rule_manifest")).required("rules")){var actual=one(db.queryForList("SELECT r.status,r.content_sha256 FROM rule_version r WHERE r.tenant_id=? AND r.rule_version=? LIMIT 2 FOR UPDATE",job.tenant(),rule.required("rule_id").asText()));same("APPROVED",str(actual,"status"));same(rule.required("sha256").asText(),str(actual,"content_sha256"));}
        {var marks=one(db.queryForList("SELECT issue_watermark,evidence_watermark FROM document_revision_state WHERE tenant_id=? AND project_id=? AND document_revision=? LIMIT 2 FOR UPDATE",job.tenant(),job.project(),job.documentRevision()));for(String key:List.of("issue_watermark","evidence_watermark")){if(!str(marks,key).equals(str(check,key)))stale();same(str(check,key),r.required("output_watermarks").required(key).asText());}}
        for(String kind:List.of("findings","coverage")){String artifact=text(r,kind+"_artifact_id");var object=one(db.queryForList("SELECT o.receipt_json,o.receipt_sha256,a.sha256 FROM document_review_object o JOIN artifact a ON a.tenant_id=o.tenant_id AND a.artifact_id=o.artifact_id WHERE o.tenant_id=? AND o.run_id=? AND o.step_id=? AND o.artifact_id=? LIMIT 2 FOR UPDATE",job.tenant(),job.run(),job.step(),artifact));same(json.hash(json.read(str(object,"receipt_json"))),str(object,"receipt_sha256"));invocations.requireOriginalProvenance(a,job,json.read(str(object,"receipt_json")).required("provenance"));same(text(r,kind+"_sha256"),str(object,"sha256"));
            if("findings".equals(kind)) {
                var declaration=one(db.queryForList("SELECT b.schema_ref,b.schema_document_sha256,a.schema_manifest_sha256,i.canonical_payload FROM artifact_content_binding b JOIN artifact a ON a.tenant_id=b.tenant_id AND a.artifact_id=b.artifact_id JOIN document_review_object_intent i ON i.tenant_id=a.tenant_id AND i.artifact_id=a.artifact_id WHERE b.tenant_id=? AND b.artifact_id=? AND b.resource_kind='DOCUMENT' AND b.resource_id=? LIMIT 2",job.tenant(),artifact,job.document()));
                var provenance=json.read(str(object,"receipt_json")).required("provenance");boolean v2=provenance.has("evidence_contract");
                var contract=new TaskReviewEvidenceContract(v2);same(contract.artifactRef(null),str(declaration,"schema_ref"));same(contract.artifactSha(),str(declaration,"schema_document_sha256"));same(contract.artifactSha(),str(declaration,"schema_manifest_sha256"));
                if(v2){same("2.0.0",text(provenance,"evidence_contract"));same(contract.artifactRef(null),text(provenance,"findings_schema_ref"));same(contract.artifactSha(),text(provenance,"findings_schema_sha256"));}
                var payload=json.read(str(declaration,"canonical_payload"));same(str(object,"sha256"),WireValues.sha256(str(declaration,"canonical_payload").getBytes(StandardCharsets.UTF_8)));
                ArtifactEvidenceBindings.bind(schemas,ArtifactBindings.ARTIFACT,payload,str(declaration,"schema_ref"),str(declaration,"schema_document_sha256")).read();
            }
        }
        var audit=one(db.queryForList("SELECT subject_id,result,resource_ref FROM audit_event WHERE tenant_id=? AND audit_id=? LIMIT 2 FOR UPDATE",job.tenant(),text(r,"audit_id")));same(job.actor(),str(audit,"subject_id"));same("SUCCESS",str(audit,"result"));same(r,json.read(str(audit,"resource_ref")));same(r,json.read(str(one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? LIMIT 2 FOR UPDATE",job.tenant(),text(r,"event_id"))),"payload")));
        return new VerifiedCompletion(job.run(),job.step(),job.inputHash(),r,str(row,"receipt_sha256"));
    }
    public final class VerifiedCompletion {
        private final String run,step,input,hash;private final JsonNode receipt;private final Thread thread=Thread.currentThread();private final TenantScope scope=TenantScope.requireCurrent();private final Map<Object,Object> resources=Map.copyOf(org.springframework.transaction.support.TransactionSynchronizationManager.getResourceMap());
        private VerifiedCompletion(String run,String step,String input,JsonNode receipt,String hash){this.run=run;this.step=step;this.input=input;this.receipt=receipt.deepCopy();this.hash=hash;}
        public void requireActive(){if(thread!=Thread.currentThread()||scope!=TenantScope.requireCurrent()||!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||!resources.equals(org.springframework.transaction.support.TransactionSynchronizationManager.getResourceMap()))deny();}
        public void requireFor(DocumentReviewExecutionService.Job job,EnterpriseAccess.Admission a)throws Exception{requireActive();same(job.run(),run);same(job.step(),step);same(job.inputHash(),input);var recovered=readOriginal(a,job);if(recovered==null)bad();same(hash,recovered.hash);same(receipt,recovered.receipt);}
        public String runId(){requireActive();return run;}public String stepId(){return step;}public String inputSha256(){return input;}public String receiptSha256(){return hash;}public JsonNode receipt(){return receipt.deepCopy();}
    }
    public final class Produced {
        private final TaskReviewEvidenceContract contract;private final DocumentReviewInvocationService.Terminal terminal;private final TaskSourceVerifierNormalizer.Normalized normalized;private final byte[] findings,coverage;
        private Produced(DocumentReviewInvocationService.Terminal t,TaskSourceVerifierNormalizer.Normalized n,byte[] f,byte[] c,TaskReviewEvidenceContract contract){this.contract=contract;terminal=t;normalized=n;findings=f.clone();coverage=c.clone();}
        void requireCurrent(EnterpriseAccess.Admission a)throws Exception{terminal.requireCurrent(a);same(contract,terminal.runtime().evidenceContract());terminal.document().requireEvidenceContract(contract);}
        String schemaRef(String kind)throws Exception{return "REVIEW_FINDINGS".equals(kind)?contract.artifactRef(null):COVERAGE_REF;}
        String schemaHash(String kind)throws Exception{return "REVIEW_FINDINGS".equals(kind)?contract.artifactSha():coverageManifest();}
        DocumentReviewInvocationService.Terminal terminal(){return terminal;}
        byte[] bytes(String kind){return switch(kind){case "REVIEW_FINDINGS"->findings.clone();case "REVIEW_COVERAGE"->coverage.clone();default->throw new IllegalArgumentException("N07 output kind");};}
        JsonNode provenance()throws Exception{var p=JsonNodeFactory.instance.objectNode().put("node_kind","N07").put("session_id",terminal.sessionId()).put("input_sha256",terminal.inputSha256()).put("baseline_sha256",terminal.document().baselineSha256()).put("rule_manifest_sha256",terminal.rules().sha256());if(contract.v2())p.put("evidence_contract",contract.version()).put("findings_schema_ref",contract.artifactRef(null)).put("findings_schema_sha256",contract.artifactSha()).put("body_schema_ref",terminal.document().bodySchemaRef()).put("body_schema_sha256",terminal.document().bodySchemaSha());p.set("independent_reads",terminal.independentReads());p.set("invocations",terminal.canonicalPins());p.set("supervision",terminal.supervisionPins());p.set("normalization",normalized.pins());return p;}
    }
    static String accessSet(String action){return derived(action,"ACCESS_SET");}static String artifact(String action,String kind){return derived(action,kind);}static String derived(String action,String kind){return UUID.nameUUIDFromBytes(("N07/"+action+"/"+kind).getBytes(StandardCharsets.UTF_8)).toString();}
    static String coverageManifest()throws Exception{try(var in=Objects.requireNonNull(DocumentReviewResultService.class.getResourceAsStream("/document-review-coverage.schema.json"))){return WireValues.sha256(in.readAllBytes());}}
    static void validateResult(JsonNode node)throws Exception{try(var in=Objects.requireNonNull(DocumentReviewResultService.class.getResourceAsStream("/document-review-result.schema.json"))){var json=new TaskSourceVerifierSchema();var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(json.read(in.readAllBytes()),com.networknt.schema.SchemaValidatorsConfig.builder().formatAssertionsEnabled(true).build());if(!schema.validate(node).isEmpty())bad();}}
    private void validateCoverage(JsonNode node)throws Exception{try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/document-review-coverage.schema.json"))){var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(json.read(in.readAllBytes()),com.networknt.schema.SchemaValidatorsConfig.builder().formatAssertionsEnabled(true).build());if(!schema.validate(node).isEmpty())bad();}}
    private Map<String,Object> meta(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,LocalDateTime at){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",h.tenantId());m.put("project_id",h.projectId());m.put("created_by",a.actorId());m.put("created_at",at);m.put("classification",h.classification());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",schemas.schemaDigest("artifacts"));return m;}
    private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
    private LocalDateTime now(){return db.queryForObject("SELECT UTC_TIMESTAMP(6)",LocalDateTime.class);}private static String id(){return UUID.randomUUID().toString();}private static <T>T one(List<T> r){if(r.size()!=1)bad();return r.get(0);}private static String str(Map<String,Object> r,String k){var v=r.get(k);if(v==null)bad();return v.toString();}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static boolean bool(JsonNode n,String k){if(!n.required(k).isBoolean())bad();return n.required(k).booleanValue();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private static void stale(){throw new TenantAccessException(ErrorCode.REVIEW_STALE);}
}
